export const aiPredictResponseCheckinsItemExpectedInternalTempRangeMax = 2;

export const AiPredictResponse = zod.object({
  estimatedDurationMinutes: zod
    .number()
    .describe(
      "Active cook time only (food on → off grill), excluding preheat and rest",
    ),
  preheatMinutes: zod
    .number()
    .describe(
      "Minutes needed to start and bring the grill up to cook temperature",
    ),
  grillLightAt: zod.coerce
    .date()
    .nullable()
    .describe("When to light\/start the grill, accounting for preheat time"),
  suggestedStartAt: zod.coerce
    .date()
    .nullable()
    .describe("When to put food on the grill"),
  estimatedFinishAt: zod.coerce
    .date()
    .nullable()
    .describe("When food comes off the grill (before rest)"),
  serveAt: zod.coerce
    .date()
    .nullable()
    .describe("When food is ready to serve (after rest)"),
  wrap: zod.object({
    wrapAtMinutes: zod
      .number()
      .describe("Minutes into the cook when meat should be wrapped"),
    method: zod
      .enum(["foil", "butcher_paper", "none"])
      .describe("Recommended wrapping material"),
    wrapTempF: zod
      .number()
      .nullable()
      .describe("Internal meat temp at which to wrap (if applicable)"),
    reason: zod
      .string()
      .describe("Why to wrap, how to do it, and what to expect"),
    restMinutes: zod
      .number()
      .describe("Recommended rest time in minutes after pulling from grill"),
  }),
  confidence: zod.enum(["low", "medium", "high"]),
  rationale: zod.string(),
  tips: zod.array(zod.string()),
  checkins: zod
    .array(
      zod
        .object({
          offsetMinutes: zod
            .number()
            .describe("Minutes after meatOnAt when this check-in should fire"),
          label: zod
            .string()
            .describe(
              'Short display label for this check-in phase (e.g. \"Bark Lock\", \"Wrap Time\")',
            ),
          coachingNote: zod
            .string()
            .describe(
              "Actionable instruction the pitmaster will act on at this moment",
            ),
          visualCues: zod
            .array(zod.string())
            .describe(
              "What to look for visually or physically when this check-in fires",
            ),
          expectedInternalTempRange: zod
            .array(zod.number())
            .min(aiPredictResponseCheckinsItemExpectedInternalTempRangeMin)
            .max(aiPredictResponseCheckinsItemExpectedInternalTempRangeMax)
            .nullish()
            .describe(
              "Expected [min, max] internal temp range at this check-in (null if not probe-based)",
            ),
        })
        .describe("A single AI-generated check-in step for a cook plan"),
    )
    .describe(
      "AI-generated check-in schedule tailored to this specific meat, technique, and cook plan. Each item fires at offsetMinutes after meatOnAt.",
    ),
  fingerprintApplied: zod
    .boolean()
    .describe(
      "True when the per-grill fingerprint adjusted the time estimate or note",
    ),
  fingerprintNote: zod
    .string()
    .nullable()
    .describe(
      "Human-readable note about how the grill's fingerprint was applied",
    ),
  fingerprintSource: zod
    .union([
      zod.literal("grill"),
      zod.literal("user"),
      zod.literal("pit_bias_only"),
      zod.literal(null),
    ])
    .nullable()
    .describe(
      "Source of the fingerprint adjustment (per-grill learned pace, user-wide fallback, or pit bias only)",
    ),
  recommendedServeAt: zod.coerce
    .date()
    .nullish()
    .describe(
      "When fromFrozen is true and the user's desiredFinishAt is too soon for a full thaw, PitMaster may suggest a later serve time that allows for proper thawing. Null when not applicable.",
    ),
  recommendedServeReason: zod
    .string()
    .nullish()
    .describe(
      "Human-readable explanation for the recommendedServeAt adjustment (e.g., why thawing requires more lead time).",
    ),
  factorBreakdown: zod
    .array(
      zod.object({
        label: zod
          .string()
          .describe(
            'Short display label for this factor (e.g. \"Base Cook Time\", \"Stall Allowance\")',
          ),
        minutes: zod
          .number()
          .describe("Time contribution in minutes (always positive)"),
        colorHex: zod
          .string()
          .describe(
            "Hex color string used to render this segment in the stacked bar",
          ),
        description: zod
          .string()
          .describe("One-sentence explanation shown in the detail sheet"),
        icon: zod.string().describe("Feather icon name for this factor"),
      }),
    )
    .optional()
    .describe(
      "Ordered list of time-contribution factors explaining what drives the cook time estimate. Present when enough context exists to build a meaningful breakdown; absent for minimal-input requests. The first item is always the base cook time; subsequent items are identified add-ons (stall, grill load, cold weather, learned pace, thaw+temper).",
    ),
  timedOut: zod
    .boolean()
    .optional()
    .describe(
      "True when the AI prediction call timed out and a fallback estimate was used instead of a live AI response.",
    ),
});

/**
 * @summary Sequence multiple cooks to all be ready at the same serve time
 */
export const aiMultiCookBodyItemsMax = 5;

export const AiMultiCookBody = zod.object({
  items: zod
    .array(
      zod.object({
        foodType: zod.string(),
        weightLbs: zod.number().nullish(),
        cookTempF: zod.number().nullish(),
        targetTempF: zod.number().nullish(),
        grillId: zod.number().nullish(),
        preheatMinutes: zod
          .number()
          .nullish()
          .describe("Minutes to preheat the grill before putting meat on"),
        cookingMethod: zod
          .string()
          .nullish()
          .describe(
            'Cooking technique selected by the user (e.g. \"Low & Slow\", \"Hot & Fast\", \"Rotisserie\"). When provided the AI should factor it into duration estimates, wrap recommendations, and notes.',
          ),
        fromFrozen: zod
          .boolean()
          .nullish()
          .describe(
            "True when this item is starting from a fully frozen state. PitMaster will factor in thaw lead-time when scheduling backwards from the serve time.",
          ),
        thawMethod: zod
          .union([
            zod.literal("fridge"),
            zod.literal("cold_water"),
            zod.literal("microwave"),
            zod.literal("counter"),
            zod.literal("cook_from_frozen"),
            zod.literal(null),
          ])
          .nullish()
          .describe(
            'Chosen thaw method when fromFrozen is true. \"fridge\" is slow and safest (~24h \/ 4–5 lbs); \"cold_water\" is faster (~1h per lb).',
          ),
        notes: zod
          .string()
          .nullish()
          .describe(
            "Free-text notes specific to this item (rub recipe, wood choice, injection brine, special instructions). PitMaster factors these into timing and technique recommendations for this cut.",
          ),
        cookingStylePreset: zod
          .string()
          .nullish()
          .describe(
            'Name of the preset style the user selected for this item (e.g. \"3-2-1 Method\", \"Texas Style\"). Mentioned for context alongside the individual technique fields.',
          ),
        grillName: zod
          .string()
          .nullish()
          .describe(
            'Human-readable name of the grill assigned to this item (e.g. \"Big Green Egg 2XL\"). Used by the server to detect shared-grill scenarios and include per-grill calibration coaching.',
          ),
        baselineEstimateMinutes: zod
          .number()
          .nullish()
          .describe(
            "Client-computed baseline active cook duration in minutes, derived from the cut's standard minsPerLb × weightLbs. The AI must treat this as a strong anchor and stay within ±25% when estimating estimatedDurationMinutes. Omitted when weight is unknown.",
          ),
        restMins: zod
          .number()
          .nullish()
          .describe(
            "Recommended rest time in minutes for this cut after pulling from the grill, from the app's cut definition. The AI should use this as the default restMinutes value.",
          ),
      }),
    )
    .min(1)
    .max(aiMultiCookBodyItemsMax),
  serveAt: zod.coerce
    .date()
    .describe("Target time when all food should be ready to serve."),
  outdoorTempF: zod
    .number()
    .nullish()
    .describe(
      "Outdoor ambient temperature in Fahrenheit. May be current conditions or a forecast for the cook day (see outdoorTempIsForecast).",
    ),
  outdoorTempIsForecast: zod
    .boolean()
    .nullish()
    .describe(
      "True when outdoorTempF is a forecasted value for the cook day (Pro). False or omitted when it is the current ambient temperature.",
    ),
  notes: zod
    .string()
    .nullish()
    .describe(
      "Optional session-level free-text notes (e.g. wood choice, rub, special instructions). PitMaster factors these into timing and tips for all items in the session.",
    ),
});

